+        visited.set(item.name, pkgDir);
+        const pkgJson = JSON.parse(readFileSync(resolve(pkgDir, "package.json"), "utf8")) as {
+          dependencies?: Record<string, string>;
+          optionalDependencies?: Record<string, string>;
+        };
